-- 1. BORRAMOS LOS REGISTROS ACTUALES PARA EVITAR DUPLICADOS
TRUNCATE TABLE inventario RESTART IDENTITY;

-- 2. ASEGURAMOS QUE LA CANTIDAD ACEPTE DECIMALES
ALTER TABLE inventario ALTER COLUMN cantidad TYPE NUMERIC(10,2);

-- 3. INSERTAMOS TODO EL INVENTARIO LIMPIO
INSERT INTO inventario (modelo, descripcion, medida, id_udm, id_marca, id_almacen, fila, id_condicion, stock_minimo, cantidad, precio_unitario)
