  v.modelo, v.descripcion, v.medida,
  (SELECT id FROM inventario_udm WHERE nombre = v.udm LIMIT 1),
  (SELECT id FROM inventario_marcas WHERE nombre = v.marca LIMIT 1),
  (SELECT id FROM inventario_almacenes WHERE nombre = v.almacen LIMIT 1),
  v.fila,
  (SELECT id FROM inventario_condiciones WHERE nombre = v.condicion LIMIT 1),
